SELECT , COUNT(h.history_id) AS historyCount, SUM(CASE WHEN h.scene_description IS NOT NULL AND h.scene_description != '' THEN 1 ELSE 0 END) AS sceneDescriptionCount, MAX(h.created_at) AS latestHistoryAt FROM shooting_location l LEFT JOIN shooting_location_history h ON h.location_id = l.location_id WHERE l.active_yn = 'Y'
AND l.sido = #{sido}
AND l.sigungu = #{sigungu}
AND (
( l.place_name LIKE CONCAT('%', #{keyword}, '%') OR l.sido LIKE CONCAT('%', #{keyword}, '%') OR l.sigungu LIKE CONCAT('%', #{keyword}, '%') OR l.lot_address LIKE CONCAT('%', #{keyword}, '%') OR l.road_address LIKE CONCAT('%', #{keyword}, '%') OR l.search_text LIKE CONCAT('%', #{keyword}, '%') OR EXISTS ( SELECT 1 FROM shooting_location_history kh WHERE kh.location_id = l.location_id AND ( kh.movie_title LIKE CONCAT('%', #{keyword}, '%') OR kh.scene_description LIKE CONCAT('%', #{keyword}, '%') ) ) )
)
GROUP BY l.location_id ORDER BY CASE WHEN l.road_address IS NOT NULL AND l.road_address != '' THEN 1 ELSE 0 END DESC, CASE WHEN l.lot_address IS NOT NULL AND l.lot_address != '' THEN 1 ELSE 0 END DESC, COUNT(h.history_id) DESC, SUM(CASE WHEN h.scene_description IS NOT NULL AND h.scene_description != '' THEN 1 ELSE 0 END) DESC, l.location_id LIMIT #{limit}

